<section class="location-picker" data-location-picker><h3><?=e(t('ปักหมุดตำแหน่งจัดส่ง (ไม่บังคับ)'))?></h3><p class="payment-help"><?=e(t('กรอกที่อยู่เองได้โดยไม่ใช้แผนที่ เมื่อกดเปิดแผนที่ เบราว์เซอร์จะติดต่อ OpenStreetMap เพื่อโหลดภาพ และเมื่อค้นหาจะส่งคำค้นไป Photon กรุณาค้นเฉพาะชื่อสถานที่ ไม่ส่งชื่อผู้รับหรือข้อมูลส่วนตัว'))?></p><button type="button" class="secondary" data-map-enable><?=e(t('เปิดแผนที่'))?></button><div data-map-tools hidden><label><?=e(t('ค้นหาชื่อสถานที่'))?><input type="search" data-map-query maxlength="120" placeholder="<?=e(t('เช่น จังหวัดเลย'))?>"></label><button type="button" class="secondary" data-map-search><?=e(t('ค้นหาสถานที่'))?></button><button type="button" class="secondary" data-map-locate><?=e(t('ใช้ตำแหน่งปัจจุบัน'))?></button><p class="payment-help"><?=e(t('ปุ่มตำแหน่งปัจจุบันจะขออนุญาตจากเบราว์เซอร์ก่อน ไม่มีการติดตามตำแหน่งเบื้องหลัง'))?></p><div data-map-results></div><div class="delivery-map" data-delivery-map></div><p><small>© OpenStreetMap contributors · Search: Photon / Komoot</small></p></div><div class="two-col"><label>Latitude<input name="latitude" inputmode="decimal" value="<?=e($locationValues['latitude']??'')?>" maxlength="12" data-latitude></label><label>Longitude<input name="longitude" inputmode="decimal" value="<?=e($locationValues['longitude']??'')?>" maxlength="13" data-longitude></label></div><button type="button" class="secondary" data-map-clear><?=e(t('ไม่บันทึกพิกัด / ล้างหมุด'))?></button><p data-map-status role="status"></p></section>
